import operator
from collections import deque
events=[]
class Count:
 def __index__(self):events.append('index');return 2
 def __getattribute__(self,name):
  if name=='__index__':events.append('ordinary')
  return object.__getattribute__(self,name)
n=Count();n.__index__=lambda:3
for value in ['x',[1],(1,),b'x',deque([1])]:
 print(value*n,n*value,operator.mul(value,n),value.__mul__(n),value.__rmul__(n))
print(events)

